# Generated by Claude (Claude Code).
"""Loss-guided sampling of training functions.

Three small networks (one per class) learn to predict the log of PeakCNN's per-function
cross-entropy from a function's parameters. Each training batch keeps a uniform class mix;
within a class, a pool of candidate parameters is drawn (POOL_FACTOR candidates per batch
slot), each candidate's loss is predicted, and the batch is sampled from the pool without
replacement with probability proportional to the predicted loss. Only the chosen
parameters are turned into functions.

Parameter encoding per class (fixed size, zero-padded to the class's longest pattern):
pattern one-hot | gaps between neighbouring knots (incl. the edges) | knot values |
pre- and postcomposition warp parameters (c each for the quadratic warp, alpha and beta each
for the cubic warp). Input sizes with the cubic warp: 0 peaks 2+2+3+4 = 11, 1 peak
4+4+5+4 = 17, 2 peaks 4+6+7+4 = 21 (quadratic: 2 fewer each).
"""

import numpy as np
import torch
import torch.nn as nn

import data
from data import NUM_CLASSES, PATTERNS, FunctionParams, evaluate_params, sample_params
from optim import Adam

HIDDEN = 32
MIN_LOSS = 1e-6  # floor before taking the log of a per-function loss


def num_inputs(label: int) -> int:
    patterns = PATTERNS[label]
    max_interior = max(len(p) for p in patterns)
    return len(patterns) + (max_interior + 1) + (max_interior + 2) + 2 * data.WARP_PARAMS[data.WARP]


def encode(params: FunctionParams, label: int) -> np.ndarray:
    """Fixed-size input vector of one function's parameters for its class's predictor."""
    patterns = PATTERNS[label]
    max_interior = max(len(p) for p in patterns)
    one_hot = np.zeros(len(patterns))
    one_hot[patterns.index(params.pattern)] = 1.0
    gaps = np.zeros(max_interior + 1)
    gaps[: len(params.knot_x) - 1] = np.diff(params.knot_x)
    values = np.zeros(max_interior + 2)
    values[: len(params.knot_y)] = params.knot_y
    return np.concatenate((one_hot, gaps, values, params.pre, params.post))


class LossPredictor(nn.Module):
    """num_inputs -> 32 -> ReLU -> 1: predicted log of the per-function cross-entropy."""

    def __init__(self, inputs: int):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(inputs, HIDDEN), nn.ReLU(), nn.Linear(HIDDEN, 1))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.net(x).squeeze(1)


class LossGuidedSampler:
    def __init__(self, num_samples: int, device, rng: np.random.Generator,
                 pool_factor: int, learning_rate: float):
        if data.WARP == "shavgulidze":
            raise ValueError("the loss-guided sampler does not support WARP = 'shavgulidze' yet")
        self.x = np.linspace(0.0, 1.0, num_samples)
        self.device = device
        self.rng = rng
        self.pool_factor = pool_factor
        self.predictors = [LossPredictor(num_inputs(c)).to(device) for c in range(NUM_CLASSES)]
        self.optimizers = [Adam(p.parameters(), lr=learning_rate) for p in self.predictors]

    def _draw(self, label: int, n: int) -> list[FunctionParams]:
        patterns = PATTERNS[label]
        return [sample_params(patterns[self.rng.integers(len(patterns))], self.rng) for _ in range(n)]

    def _encode(self, params: list[FunctionParams], label: int) -> torch.Tensor:
        enc = np.stack([encode(p, label) for p in params]).astype(np.float32)
        return torch.from_numpy(enc).to(self.device)

    def sample_batch(self, batch_size: int):
        """Return (functions, labels, inputs): float32 (batch, num_samples), int64 (batch,),
        and per class (positions in the batch, encoded parameters on the device)."""
        labels = self.rng.integers(0, NUM_CLASSES, batch_size)
        functions = np.empty((batch_size, len(self.x)), dtype=np.float32)
        inputs = {}
        for c in range(NUM_CLASSES):
            positions = np.flatnonzero(labels == c)
            if len(positions) == 0:
                continue
            pool = self._draw(c, self.pool_factor * len(positions))
            pool_enc = self._encode(pool, c)
            with torch.no_grad():
                predicted = self.predictors[c](pool_enc).cpu().numpy().astype(np.float64)
            weights = np.exp(predicted - predicted.max())  # proportional to the predicted loss
            chosen = self.rng.choice(len(pool), size=len(positions), replace=False,
                                     p=weights / weights.sum())
            for pos, k in zip(positions, chosen):
                functions[pos] = evaluate_params(pool[k], self.x)
            inputs[c] = (torch.from_numpy(positions).to(self.device), pool_enc[torch.from_numpy(chosen).to(self.device)])
        return functions, labels.astype(np.int64), inputs

    def sample_uniform(self, n: int):
        """Uniformly sampled functions with their encodings (for evaluation): same return format."""
        labels = self.rng.integers(0, NUM_CLASSES, n)
        functions = np.empty((n, len(self.x)), dtype=np.float32)
        inputs = {}
        for c in range(NUM_CLASSES):
            positions = np.flatnonzero(labels == c)
            if len(positions) == 0:
                continue
            params = self._draw(c, len(positions))
            for pos, p in zip(positions, params):
                functions[pos] = evaluate_params(p, self.x)
            inputs[c] = (torch.from_numpy(positions).to(self.device), self._encode(params, c))
        return functions, labels.astype(np.int64), inputs

    def update(self, per_function_loss: torch.Tensor, inputs) -> None:
        """One training step of each predictor towards log(per-function cross-entropy)."""
        target_all = torch.log(per_function_loss.detach().clamp_min(MIN_LOSS))
        for c, (positions, enc) in inputs.items():
            prediction = self.predictors[c](enc)
            loss = ((prediction - target_all[positions]) ** 2).mean()
            self.optimizers[c].zero_grad()
            loss.backward()
            self.optimizers[c].step()

    def predict(self, inputs, n: int) -> torch.Tensor:
        """Predicted log-loss for every function of a batch returned by sample_* (on the device)."""
        out = torch.empty(n, device=self.device)
        with torch.no_grad():
            for c, (positions, enc) in inputs.items():
                out[positions] = self.predictors[c](enc)
        return out
